const lead=typeof $json.raw_payload==='string'?JSON.parse($json.raw_payload):$json.raw_payload;
const prompt=[
  'Return only JSON with manualReview (boolean) and summary (string). Do not assign priority.',
  'Set manualReview to true only for spam, abusive content, contradictory details, or an inquiry too incomplete to understand.',
  'A coherent business inquiry with a valid requested service, company, timeline, and explanatory message is not manual review: set manualReview to false.',
  'This lead passed schema validation and gave WhatsApp contact consent.',
  'Lead: '+JSON.stringify(lead)
].join(' ');
return {json:{emailKey:$json.email_key,operationalPriority:$json.operational_priority,ollamaBody:{model:'qwen3.5:9b',stream:false,format:'json',options:{think:false},prompt}}};

const s=$('Validate Ollama response').item.json;
const c=$('Claim lead for processing').item.json;
const l=typeof c.raw_payload==='string'?JSON.parse(c.raw_payload):c.raw_payload;
const parts=l.fullName.trim().split(/\s+/);
const firstName=parts.length>1?parts.slice(0,-1).join(' '):l.fullName;
const lastName=parts.length>1?parts.at(-1):'';
return {json:{emailKey:s.emailKey,hubspotBody:{inputs:[{idProperty:'email',id:l.email,properties:{
  email:l.email,
  firstname:firstName,
  lastname:lastName,
  phone:l.phone,
  company:l.company || '',
  lead_service:({automation:'Automation',consulting:'Consulting',web_development:'Web development',other:'Other'})[l.service],
  lead_timeline:({asap:'As soon as possible',this_month:'This month',exploring:'Exploring options'})[l.timeline],
  lead_priority:({high:'High',normal:'Normal',low:'Low'})[s.operationalPriority],
  lead_locale:({en:'English',es:'Spanish'})[l.locale],
  lead_message:l.message,
  lead_summary:s.summary
}}]}}};
